import json,re
from pathlib import Path

def extract_plans(tid):
    p=Path(f'/Users/amin/.cursor/projects/Users-amin-dev-p-projects-armenia-resume/agent-transcripts/{tid}')
    files=list(p.glob('*.jsonl'))
    if not files: return
    print(f'\n======== {tid} ========')
    for f in files:
      for line in open(f):
        try: o=json.loads(line)
        except: continue
        msg=o.get('message') or {}
        content=msg.get('content')
        if not isinstance(content,list): continue
        for part in content:
          if not isinstance(part,dict): continue
          if part.get('type')=='tool_use' and part.get('name') in ('CreatePlan','Write'):
