              print(f'--- tool={part["name"]} name={name} ---')
              print(plan[:2000])
              print('...')
          if part.get('type')=='text':
            t=part.get('text') or ''
            if 'CreatePlan' in t or (t.startswith('#') and any(k in t.lower() for k in ['design','hallmark','website','marketing','mcp'])):
              pass

